application/json

@{
var granted = ((string)context.Variables["grantedModels"])
.Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries);
var created = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
var data = new JArray();
foreach (var m in granted) {
data.Add(new JObject(
new JProperty("id", m.Trim()),
new JProperty("object", "model"),
new JProperty("created", created),
new JProperty("owned_by", "foundry-hackathon-gateway")
));
}
return new JObject(
new JProperty("object", "list"),
new JProperty("data", data)
).ToString();
}



<set-variable name="requestedModel" value="@{
try {
var fromBody = context.Request.Body.As(preserveContent: true)["model"]?.ToString();
if (!string.IsNullOrEmpty(fromBody)) { return fromBody.Trim().ToLowerInvariant(); }
} catch { }
return "";
}" />





application/json

@{
return new JObject(
new JProperty("error", new JObject(
new JProperty("code", "model_not_permitted"),
new JProperty("type", "permission_error"),
new JProperty("message", "The model '" + (string)context.Variables["requestedModel"] + "' is not included in your key. Yours: " + (string)context.Variables["grantedModels"] + ".")
))
).ToString();
}




<when condition="@{
if ((string)context.Variables["requestedModel"] != "pro") { return false; }
try { return context.Request.Body.As(preserveContent: true)["tools"] != null; }
catch { return false; }
}">






<set-variable name="deployment" value="@{
var alias = (string)context.Variables["requestedModel"];
foreach (var entry in "{{hackgw-model-map}}".Split(';')) {
var idx = entry.IndexOf('=');
if (idx <= 0) { continue; }
var key = entry.Substring(0, idx).Trim().ToLowerInvariant();
var val = entry.Substring(idx + 1).Trim();
if (key == alias && val.Length > 0) { return val; }
}
return "";
}" />





application/json

@{
return new JObject(
new JProperty("error", new JObject(
new JProperty("code", "model_not_configured"),
new JProperty("type", "invalid_request_error"),
new JProperty("message", "The model '" + (string)context.Variables["requestedModel"] + "' is granted by your key but is not configured on this gateway. Tell an organiser - this is a gateway configuration problem, not a problem with your key.")
))
).ToString();
}









