@("Bearer " + (string)context.Variables["msi-token"])


@{
var body = context.Request.Body.As(preserveContent: true);
body["model"] = (string)context.Variables["deployment"];
var cap = int.Parse("{{hackgw-max-output-tokens}}");
foreach (var field in new[] { "max_tokens", "max_completion_tokens" }) {
int requested;
if (body[field] == null
|| !int.TryParse(body[field].ToString(), out requested)
|| requested <= 0
|| requested > cap) {
body[field] = cap;
}
}
body["n"] = 1;
return body.ToString();
}

